// Reads the static catalog from public/data/greek-alphabet/: words.json lists
// the terms, each with a <term>.webp image and an audio/<term>.mp3 clip
// (generated by cms/greek_alphabet/build_audio.py).
const DATA_URL = '/data/greek-alphabet'

export type Word = { term: string; image: string; audio: string }

let wordsPromise: Promise<Word[]> | null = null

function toWord(term: string): Word {
  const file = encodeURIComponent(term)
  return { term, image: `${DATA_URL}/${file}.webp`, audio: `${DATA_URL}/audio/${file}.mp3` }
}

export function getWords(): Promise<Word[]> {
  wordsPromise ??= fetch(`${DATA_URL}/words.json`)
    .then((response) => {
      if (!response.ok) throw new Error(`Failed to load words (${response.status})`)
      return response.json() as Promise<string[]>
    })
    .then((terms) => terms.map(toWord))
  return wordsPromise
}
